package bowling

import "errors"

// Game keeps track of the rolls in a game of bowling.
type Game struct {
	rolls []int
}

// NewGame returns a new, empty Game.
func NewGame() *Game {
	return &Game{}
}

// nextRollState reports the number of pins still standing in the frame the
// next roll belongs to, and whether the game is already complete.
func (g *Game) nextRollState() (pinsStanding int, over bool) {
	frame := 0
	for i := 0; i < len(g.rolls); {
		if frame < 9 {
			if g.rolls[i] == 10 {
				// Strike: the frame is complete with a single roll.
				i++
			} else {
				if i+1 >= len(g.rolls) {
					// Incomplete frame: one non-strike roll so far.
					return 10 - g.rolls[i], false
				}
				// Two rolls complete the frame.
				i += 2
			}
			frame++
		} else {
			// Tenth frame: bonus rolls are allowed after a strike or spare.
			n := len(g.rolls) - i
			switch n {
			case 0:
				return 10, false
			case 1:
				if g.rolls[i] == 10 {
					return 10, false
				}
				return 10 - g.rolls[i], false
			case 2:
				first, second := g.rolls[i], g.rolls[i+1]
				if first == 10 {
					if second == 10 {
						return 10, false
					}
					return 10 - second, false
				}
				if first+second == 10 {
					return 10, false
				}
				// Open frame: the game is over.
				return 0, true
			default:
				// A third roll was made: the game is over.
				return 0, true
			}
		}
	}
	return 10, false
}

// Roll records a single throw, returning an error if it is not a legal roll.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errors.New("negative rolls are invalid")
	}
	if pins > 10 {
		return errors.New("pin count exceeds pins on the lane")
	}
	pinsStanding, over := g.nextRollState()
	if over {
		return errors.New("cannot roll after game is over")
	}
	if pins > pinsStanding {
		return errors.New("pin count exceeds pins on the lane")
	}
	g.rolls = append(g.rolls, pins)
	return nil
}

// Score returns the total score for a completed game, or an error if the
// game is not yet complete.
func (g *Game) Score() (int, error) {
	if _, over := g.nextRollState(); !over {
		return 0, errors.New("score cannot be taken until the end of the game")
	}
	rolls := g.rolls
	score := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case rolls[i] == 10:
			// Strike.
			if frame == 9 {
				score += rolls[i] + rolls[i+1] + rolls[i+2]
			} else {
				score += 10 + rolls[i+1] + rolls[i+2]
			}
			i++
		case rolls[i]+rolls[i+1] == 10:
			// Spare.
			if frame == 9 {
				score += rolls[i] + rolls[i+1] + rolls[i+2]
			} else {
				score += 10 + rolls[i+2]
			}
			i += 2
		default:
			// Open frame.
			score += rolls[i] + rolls[i+1]
			i += 2
		}
	}
	return score, nil
}

